{"packet_id": "D040-01", "doc_id": "D040", "jurisdiction": "Los Angeles, CA", "category": "just_cause_eviction", "lifecycle": "enacted", "title": "LA Just Cause Ordinance: just cause and relocation assistance", "requirement": "A landlord may not terminate a covered tenancy without just cause, and must pay relocation assistance for no-fault evictions; at-fault tenants get none.", "key_value": null, "coverage_conditions": "Most Los Angeles residential rentals not regulated by the RSO, after six months in the unit or expiry of the original lease, whichever comes first; includes buildings newer than October 1, 1978 and a single-family dwelling.", "applicability": {"built_on_or_before": null, "built_after": null, "date_basis": null, "min_units": null, "max_units": null, "owner_dependent": true, "other": "tenant in the unit at least 6 months or original lease expired"}, "exemptions": "Transient hotels, licensed care facilities, fraternity or sorority houses, owner’s roommate, some cooperatives, some non-profit homeless or substance-abuse treatment facilities, and some HACLA or government-owned properties.", "penalty": null, "effective_date": null, "citation": "Los Angeles Just Cause Ordinance: just cause eviction and relocation assistance", "quoted_span": "It prohibits terminations of tenancies without just cause and requires relocation assistance for no-fault evictions.", "interaction": "JCO covers units not regulated by the City’s Rent Stabilization Ordinance; RSO units are covered by the RSO instead.", "confidence": 0.8, "conflict_flag": false, "conflict_note": null}
{"packet_id": "D040-01", "doc_id": "D040", "jurisdiction": "CA", "category": "rent_increase_limits", "lifecycle": "enacted", "title": "California Tenant Protection Act AB 1482 annual rent cap", "requirement": "Annual rent increases on covered units are limited to 5% plus the regional cost-of-living change, or 10%, whichever is lower; the allowable figure was 8.9% for August 1, 2024 to July 31, 2025.", "key_value": "5% + CPI, max 10%; 8.9% for 2024-08-01 to 2025-07-31", "coverage_conditions": "Buildings older than 15 years on a rolling basis that are not already covered by the Los Angeles RSO or another listed exemption.", "applicability": {"built_on_or_before": null, "built_after": null, "date_basis": "construction_date", "min_units": null, "max_units": null, "owner_dependent": true, "other": "buildings older than 15 years, rolling basis"}, "exemptions": "Units constructed within the last 15 years, deed- or regulatory-restricted affordable units, certain dormitories, a two-unit property whose second unit was owner-occupied for the whole tenancy, some single-family homes and condominiums, and RSO units.", "penalty": null, "effective_date": "2024-08-01", "citation": "Cal. Civ. Code § 1947.12", "quoted_span": "Effective August 1, 2024 to July 31, 2025, the maximum allowable increase is\n8.9%", "interaction": "State law applies where the JCO does not regulate rent increases; units already under the City RSO are exempt from it.", "confidence": 0.8, "conflict_flag": false, "conflict_note": null}
{"packet_id": "D040-01", "doc_id": "D040", "jurisdiction": "Los Angeles, CA", "category": "just_cause_eviction", "lifecycle": "enacted", "title": "LA non-payment eviction threshold, Fair Market Rent", "requirement": "A landlord may not evict a tenant who falls behind in rent unless the tenant owes more than the Fair Market Rent for that bedroom size.", "key_value": "rent owed must exceed Fair Market Rent", "coverage_conditions": "All RSO and JCO rental units in the City of Los Angeles.", "applicability": {"built_on_or_before": null, "built_after": null, "date_basis": null, "min_units": null, "max_units": null, "owner_dependent": false, "other": null}, "exemptions": null, "penalty": null, "effective_date": "2023-03-27", "citation": "Los Angeles Just Cause Ordinance: non-payment eviction, Fair Market Rent threshold", "quoted_span": "Effective March 27, 2023, landlords may not evict a tenant who falls behind in rent unless the tenant owes an amount higher than the Fair Market Rent (FMR).", "interaction": null, "confidence": 0.8, "conflict_flag": false, "conflict_note": null}
{"packet_id": "D040-01", "doc_id": "D040", "jurisdiction": "Los Angeles, CA", "category": "just_cause_eviction", "lifecycle": "enacted", "title": "LA eviction notices must be filed with LAHD", "requirement": "Every eviction notice served on a tenant in Los Angeles must be filed with the Los Angeles Housing Department within three business days of service.", "key_value": "3 business days", "coverage_conditions": "All JCO and RSO rental properties in the City of Los Angeles.", "applicability": {"built_on_or_before": null, "built_after": null, "date_basis": null, "min_units": null, "max_units": null, "owner_dependent": false, "other": null}, "exemptions": null, "penalty": null, "effective_date": null, "citation": "Los Angeles Just Cause Ordinance: eviction notice filing with LAHD", "quoted_span": "All eviction notices issued to tenants in the City of Los Angeles must be filed with LAHD within three (3) business days of service on the tenant.", "interaction": null, "confidence": 0.75, "conflict_flag": false, "conflict_note": null}
